const $=id=>document.getElementById(id),esc=s=>String(s??'Not disclosed').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('sindy-saved-jobs')||'[]'))}catch{}let savedOnly=false,hideClearance=false,dateOrder='none',sizeOrder=null;let progress={};try{progress=JSON.parse(localStorage.getItem('sindy-job-progress')||'{}')}catch{}const norm=s=>String(s||'').toLowerCase();const text=v=>Array.isArray(v)?v.join('; '):v||'Not disclosed';
function short(s,n=85){s=text(s);return s.length>n?s.slice(0,n).replace(/\s+\S*$/,'')+'…':s}function prep(j){let t=text(j.applicationRequirements);let bits=[];if(/portfolio|work samples/i.test(t)&&!/portfolio.*not disclosed/i.test(t))bits.push('Portfolio');if(/resume|cv/i.test(t)&&!/resume.*requirements/i.test(t))bits.push('Résumé');if(/cover letter required|resume and cover letter required/i.test(t))bits.push('Cover letter');if(/clearance|TS\/SCI|Top Secret|Public Trust|citizenship|US citizen/i.test(t))bits.push('Eligibility / clearance');return bits.join(' · ')||'Check application details'}function checklist(j){const s=[text(j.applicationRequirements),j.experienceRequirements||j.experienceRequirement||'',j.educationRequirement||'',j.qualificationsFlexibility||j.flexibility||''].join(' ');let a=[];const ys=[...s.matchAll(/\b(\d+)(?:[–-]\d+)?\+?\s*years?/ig)].map(x=>Number(x[1]));if(ys.length){const y=Math.max(...ys);a.push((y<=7?'✓ ':'◔ ')+y+'+ years'+(y===7?' · close match':y>7?' · review':''))}else a.push('— Years not specified');if(/bachelor/i.test(s)&&!/no bachelor|bachelor.{0,35}not|required degree not|no basic degree/i.test(s))a.push('✓ Bachelor’s degree');if(/no.*sponsorship|not.*sponsor/i.test(s))a.push('✓ No sponsorship needed');if(/equivalent|equivalency|or relevant experience/i.test(s)&&!/equivalent.{0,70}not|equivalency.{0,70}not|no.{0,30}equivalen/i.test(s))a.push('↔ Experience alternative stated');else if(/below|less than|fewer|welcome/i.test(j.qualificationsFlexibility||''))a.push('↔ Flexible experience stated');if(/clearance|TS\/SCI|Top Secret|Public Trust/i.test(s))a.push('? Clearance · confirm');if(/US citizen|citizenship/i.test(s))a.push('? Citizenship · confirm');return '<ul class="checklist">'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'}function materials(j){const s=text(j.applicationRequirements);let a=[];if(/resume|cv/i.test(s)&&!/resume.*requirements/i.test(s))a.push('□ Résumé');if(/portfolio|work samples/i.test(s)&&!/portfolio.*not disclosed|check posting.*portfolio/i.test(s))a.push('□ Portfolio / samples');if(/cover letter required|resume and cover letter required/i.test(s))a.push('□ Cover letter');if(!a.length)a.push('□ Check submission form');return '<ul class="checklist">'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'}function clearance(j){const s=[j.title,j.applicationRequirements,j.clearance].filter(Boolean).join(' ');return /security clearance|TS\/SCI|Top Secret|Public Trust|CBP suitability|\bCAC\b|Secret or TS|CI poly/i.test(s)&&!/no security clearance required/i.test(s)}function age(j){return j.postedDate?Math.round((Date.parse('2026-10-20')-Date.parse(j.postedDate))/86400000):null}function dateMatch(j){const a=age(j),v=$('dateFilter').value;return v==='all'||v==='unknown'&&a===null||v==='30'&&a!==null&&a<=30||v==='90'&&a!==null&&a<=90||v==='older'&&a!==null&&a>90}function posting(j){if(!j.postedDate)return '<span class="muted">Not found</span>';return '<time datetime="'+esc(j.postedDate)+'">'+new Date(j.postedDate+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})+'</time><div class="tiny">'+age(j)+' days at review</div>'}function sizeValue(j,key){const s=text(j[key]);if(/not disclosed|unknown|not verified/i.test(s))return null;if(key==='teamSize'){if(/first and only designer/i.test(s))return 1;const m=s.match(/(\d[\d,]*)\+? across/);return m?Number(m[1].replace(/,/g,'')):null}const m=s.match(/(\d[\d,]*(?:\.\d+)?)\s*(million|thousand)?/i);return m?Number(m[1].replace(/,/g,''))*(m[2]?.toLowerCase()==='million'?1000000:m[2]?.toLowerCase()==='thousand'?1000:1):null}function compareSize(a,b){const x=sizeValue(a,sizeOrder.key),y=sizeValue(b,sizeOrder.key);return x===null&&y===null?0:x===null?1:y===null?-1:(x-y)*sizeOrder.direction}function progressCell(j){return ['reviewed','applied'].map(k=>'<label class="progress-label"><input type="checkbox" data-progress="'+k+'" data-job="'+esc(j.url)+'" '+(progress[j.url]?.[k]?'checked':'')+'>'+k[0].toUpperCase()+k.slice(1)+'</label>').join('')}function render(){const q=norm($('search').value);const rows=jobs.filter(j=>dateMatch(j)&&(!hideClearance||!clearance(j))&&(!q||norm(Object.values(j).join(' ')).includes(q))&&($('region').value==='all'||j.region===$('region').value)&&($('mode').value==='all'||(norm(j.workMode).replace(/on.site/g,'onsite').includes($('mode').value)&&!($('mode').value==='remote'&&/not remote|no remote/.test(norm(j.workMode)))))&&($('verification').value==='all'||j.verified)&&(!savedOnly||saved.has(j.url)));if(sizeOrder)rows.sort(compareSize);if(dateOrder!=='none')rows.sort((a,b)=>!a.postedDate&&!b.postedDate?0:!a.postedDate?1:!b.postedDate?-1:(dateOrder==='newest'?b.postedDate.localeCompare(a.postedDate):a.postedDate.localeCompare(b.postedDate)));$('count').textContent=`${rows.length} of ${jobs.length} opportunities · verified and indexed leads labeled separately`;$('empty').hidden=rows.length>0;$('list').innerHTML=rows.map(j=>`<tr><td data-label="Company · what they do"><strong>${esc(j.company)}</strong><p class="company-desc">${esc(j.companyDescription||'Company context not yet sourced')}</p></td><td data-label="Role"><a class="title" href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">${esc(j.title)} ↗</a><span class="tag">${j.region==='remote'?'US remote':'DMV'}</span>${clearance(j)?'<span class="tag clearance" title="Clearance or government access requirement; see requirements">◈ Clearance / access</span>':''}<span class="tag">${j.verified?'Detail page checked':'Indexed only — recheck'}</span><button class="save" data-url="${esc(j.url)}" aria-pressed="${saved.has(j.url)}">${saved.has(j.url)?'Saved ✓':'Save role'}</button></td><td data-label="Location & arrangement">${esc(j.location)}<p>${esc(short(j.workMode,65))}</p></td><td data-label="Employer-listed pay">${esc(text(j.salary))}</td><td data-label="Posted">${posting(j)}</td><td data-label="Company size">${esc(short(j.companySize,65))}${j.sizeSource&&/^https?:/.test(j.sizeSource)?`<p><a href="${esc(j.sizeSource)}" target="_blank" rel="noopener noreferrer">Source ↗</a></p>`:''}</td><td data-label="Team size">${esc(j.teamSize)}</td><td data-label="Qualifications & flexibility">${checklist(j)}</td><td data-label="Application materials">${materials(j)}<details class="cell-detail"><summary>Requirements & source</summary><p>${esc(text(j.applicationRequirements))}</p><p>${esc(j.experienceRequirements||j.experienceRequirement||'')}</p><p>${esc(j.educationRequirement||'')}</p><p>${esc(j.qualificationsFlexibility||j.flexibility||'')}</p><p>${esc(text(j.sourceNote))}</p><p>Checked ${esc(j.checkedDate)}</p>${j.postedDate?`<p>Posted date: ${esc(j.postedDate)} · ${esc(j.postedDateSource)}. Dates may reflect reposting and do not establish current hiring intent.</p>`:''}${j.hiringContact&&j.hiringContact!=='Not disclosed'?`<div class="contact-detail"><strong>Hiring contact</strong><p>${esc(text(j.hiringContact))}${j.contactRole&&j.contactRole!=='Not disclosed'?`<p>${esc(j.contactRole)}</p>`:''}${j.contactUrl&&/^https?:/.test(j.contactUrl)?`<p><a href="${esc(j.contactUrl)}" target="_blank" rel="noopener noreferrer">Public bio / source ↗</a></p>`:''}${j.contactEmail&&j.contactEmail.includes('@')?`<p>${esc(j.contactEmail)}</p>`:''}</p></div>`:''}</details></td><td data-label="Entity evidence">${j.registrationUrl?`<a href="${esc(j.registrationUrl)}" target="_blank" rel="noopener noreferrer">${esc(j.registrationLabel)} ↗</a>`:'Not verified'}${j.registrationUrl?`<details><summary>What this verifies</summary><p>${esc(j.entityName)}</p><p>${esc(j.registrationNote)}</p></details>`:''}</td><td data-label="My progress">${progressCell(j)}</td></tr>`).join('');document.querySelectorAll('[data-progress]').forEach(c=>c.onchange=()=>{progress[c.dataset.job]={...progress[c.dataset.job],[c.dataset.progress]:c.checked};try{localStorage.setItem('sindy-job-progress',JSON.stringify(progress))}catch{ $('count').textContent+=' · Browser storage unavailable; changes may not persist'}});document.querySelectorAll('.save').forEach(b=>b.onclick=()=>{saved.has(b.dataset.url)?saved.delete(b.dataset.url):saved.add(b.dataset.url);try{localStorage.setItem('sindy-saved-jobs',JSON.stringify([...saved]))}catch{}render()})}
$('mobileSort').onchange=()=>{const v=$('mobileSort').value;sizeOrder=v==='companySize'||v==='teamSize'?{key:v,direction:1}:null;dateOrder=v==='newest'||v==='oldest'?v:'none';render()};$('mobileDate').onchange=()=>{$('dateFilter').value=$('mobileDate').value;render()};['companySize','teamSize'].forEach(key=>$(key+'Sort').onclick=()=>{sizeOrder={key,direction:sizeOrder?.key===key?-sizeOrder.direction:1};dateOrder='none';$('dateSort').textContent='Posted ⇅';$('postedHeading').setAttribute('aria-sort','none');['companySize','teamSize'].forEach(k=>{$(k+'Sort').textContent=(k==='companySize'?'Company size':'Team size')+(k===key?(sizeOrder.direction===1?' ↑':' ↓'):' ⇅');$(k+'Heading').setAttribute('aria-sort',k===key?(sizeOrder.direction===1?'ascending':'descending'):'none')});render()});$('dateFilter').onchange=render;$('dateSort').onclick=()=>{sizeOrder=null;['companySize','teamSize'].forEach(k=>$(k+'Heading').setAttribute('aria-sort','none'));dateOrder=dateOrder==='newest'?'oldest':'newest';$('dateSort').textContent=dateOrder==='newest'?'Posted ↓':'Posted ↑';$('postedHeading').setAttribute('aria-sort',dateOrder==='newest'?'descending':'ascending');render()};$('clearance').onclick=()=>{hideClearance=!hideClearance;$('clearance').setAttribute('aria-pressed',hideClearance);$('clearance').textContent=hideClearance?'Clearance roles hidden':'Hide clearance roles';render()};['search','region','mode','verification'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('saved').onclick=()=>{savedOnly=!savedOnly;$('saved').setAttribute('aria-pressed',savedOnly);render()};$('reset').onclick=()=>{$('search').value='';['region','mode','verification'].forEach(id=>$(id).value='all');savedOnly=false;$('saved').setAttribute('aria-pressed','false');render()};render();
